cypher:
// Which documents does this client still have to deliver, and on what basis?
// Only where the office's sector requires customer due diligence on $on (not for traders in goods from 2026, nor for appraisers).
// For every required document type that no document in the file proves: the legal form rule, the law article (with the quote) or the risk trigger behind it.
MATCH (c:Client)-[q:REQUIRES]->(t:DocumentType)
WHERE NOT EXISTS { (:Document)-[:OF_TYPE]->(t) }
MATCH (c)-[:CLIENT_OF]->(:Institution)-[:IN_SECTOR]->(sec:Sector) WHERE coalesce(sec.cdd, true) AND (sec.cdd_until IS NULL OR sec.cdd_until >= $on) AND (sec.cdd_from IS NULL OR sec.cdd_from <= $on)
OPTIONAL MATCH (c)-[:HAS_LEGAL_FORM]->(f:LegalForm)-[ld:REQUIRES_DOC]->(t)
OPTIONAL MATCH (c)-[:SUBJECT_TO]->(o:Obligation)-[:PROVEN_BY]->(t)
OPTIONAL MATCH (a:Article)-[i:IMPOSES]->(o)
OPTIONAL MATCH (c)-[:HAS_TRIGGER]->(g:RiskTrigger)-[:ADDS_REQUIREMENT]->(t)
RETURN t.name AS missing_document,
       collect(DISTINCT CASE WHEN f IS NULL THEN null ELSE f.abbr + ': ' + coalesce(ld.local, ld.when) END) AS legal_form_rule,
       collect(DISTINCT a.ref + CASE WHEN a.verify THEN ' (to verify)' ELSE ' (checked)' END) AS law_articles,
       collect(DISTINCT g.name) AS risk_triggers
ORDER BY missing_document;

// Why is this document type required? Follow the chain Client -> Obligation <- Article -> Law, with the passage and the source.
// param: doctype (e.g. source_of_funds, person_id, proof_of_address)
MATCH (c:Client)-[:SUBJECT_TO]->(o:Obligation)-[:PROVEN_BY]->(t:DocumentType {key:$doctype})
MATCH (a:Article)-[i:IMPOSES]->(o)
OPTIONAL MATCH (a)-[:PART_OF]->(l:Law)
RETURN t.name AS document, o.text AS obligation, i.condition AS applies, a.ref AS article, l.title AS law, left(i.quote, 220) AS passage, a.source_url AS source, CASE WHEN a.verify THEN 'to verify' ELSE 'checked' END AS text_status
ORDER BY article;

// PEPs in the structure, how they are connected to the client, and the signals raised about them
MATCH (v:Person {pep:true})
MATCH p = (v)-[:OWNS|DIRECTOR_OF]->{1,3}(c:Client)
OPTIONAL MATCH (s:Signal)-[:ABOUT]->(v)
RETURN v.name AS pep, v.pep_role AS role, [n IN nodes(p) | n.name] AS path, [r IN relationships(p) | type(r) + ' ' + coalesce(toString(r.pct) + '%', '')] AS links, collect(DISTINCT s.title) AS signals;

// For every question in the client acceptance: the answer, its status and the documents (with the place in the document) it rests on
MATCH (c:Client)-[:HAS_QUESTION]->(q:Question)
OPTIONAL MATCH (d:Document)-[a:ANSWERS]->(q)
RETURN q.id AS id, q.text AS question, q.status AS status, q.answer AS answer, collect(d.id + ' ' + d.title + ' @ ' + a.where) AS evidence
ORDER BY id;

// Full-text search in the documents of the case. param: term (e.g. nominee, director, Panama)
MATCH (d:Document) SEARCH d IN (FULLTEXT INDEX doc_text FOR $term LIMIT 5) SCORE AS relevance
OPTIONAL MATCH (d)-[:MENTIONS]->(p:Party)
RETURN d.id AS doc, d.title AS title, relevance, collect(p.name) AS mentions
ORDER BY relevance DESC;

// Full-text search in the law articles copied into the case. param: term (e.g. "source of wealth", address)
MATCH (a:Article) SEARCH a IN (FULLTEXT INDEX article_text FOR $term LIMIT 5) SCORE AS relevance
OPTIONAL MATCH (a)-[i:IMPOSES]->(o:Obligation)
RETURN a.ref AS article, relevance, collect(DISTINCT o.text) AS obligations, left(a.text_en, 200) AS text, a.source_url AS source
ORDER BY relevance DESC;

// Where in the scanned documents does a term appear, on which page and position, and how sure is the OCR? param: term (e.g. nominee, getekend, bevoegd)
MATCH (k:Chunk) SEARCH k IN (FULLTEXT INDEX chunk_text FOR $term LIMIT 8) SCORE AS relevance
MATCH (d:Document)-[:HAS_CHUNK]->(k)
RETURN d.id AS doc, d.file AS file, k.page AS page, k.bbox AS box_px, k.confidence AS ocr_conf, k.low_conf_words AS unsure_words, left(replace(k.text, '\n', ' | '), 140) AS text, relevance
ORDER BY relevance DESC;

// Every entity in the structure, its legal form, and the grounds on which its beneficial owners are determined (from the legal-form inventory and the UBO rule of the office)
MATCH (x) WHERE (x:Client OR x:Party) AND EXISTS { (x)-[:HAS_LEGAL_FORM]->() }
MATCH (x)-[:HAS_LEGAL_FORM]->(f:LegalForm)
OPTIONAL MATCH (f)-[:TESTED_BY]->(g:UboGround)
RETURN x:Client AS client, x.name AS entity, f.abbr + ' (' + split(f.id, ':')[0] + ')' AS legal_form, f.category AS category, f.entity_type AS tested_as,
       collect(g.ground + CASE WHEN g.op IN ['>', '>='] THEN ' ' + g.op + ' ' + toString(g.threshold) + '%' ELSE '' END) AS grounds_here,
       f.ubo_rule AS ubo_rule_for_this_form, f.law AS law, CASE WHEN f.verify THEN 'to verify' ELSE 'checked' END AS status
ORDER BY client DESC, entity;

// Which sectors are there, per category, and are they obliged today?
// from: - | yields: Sector
MATCH (s:Sector)-[:IN_CATEGORY]->(c:SectorCategory)
RETURN 'Sector' AS _type, s.id AS _id, c.name_nl AS category, s.local AS sector,
       CASE WHEN s.status = 'no_aml' THEN 'supervised, not an obliged entity' WHEN s.obliged_from IS NULL THEN 'obliged (Wwft)' ELSE 'obliged from ' + s.obliged_from END AS status, c.order AS cat_order
ORDER BY cat_order, sector

// Which authorities are there, and in how many sectors are they the AML supervisor or have another role?
// from: - | yields: Regulator
MATCH (g:Regulator)-[v:SUPERVISES]->(s:Sector)
RETURN 'Regulator' AS _type, g.id AS _id, g.short AS authority, g.name AS name, count(DISTINCT CASE WHEN v.aml THEN s END) AS sectors_as_aml_supervisor, count(DISTINCT CASE WHEN NOT v.aml THEN s END) AS sectors_other_role
ORDER BY sectors_as_aml_supervisor DESC, sectors_other_role DESC, authority

// Which legislation is there, and to how many sectors does it apply?
// from: - | yields: Law
MATCH (l:Law)<-[:SUBJECT_TO]-(s:Sector)
RETURN 'Law' AS _type, l.id AS _id, l.short AS law, l.title AS title, CASE WHEN l.valid_from IS NULL OR l.valid_from <= $on THEN 'in force' ELSE 'from ' + l.valid_from END AS status, count(DISTINCT s) AS sectors
ORDER BY sectors DESC, law

// Who supervises this sector, in which role, and on what legal basis?
// from: Sector | yields: Regulator
MATCH (g:Regulator)-[v:SUPERVISES]->(s:Sector {id:$id})
RETURN 'Regulator' AS _type, g.id AS _id, g.short AS authority, CASE WHEN v.aml THEN 'AML supervisor' ELSE replace(coalesce(v.role, ''), '_', ' ') END AS role, g.basis AS legal_basis, CASE WHEN g.basis_verify THEN 'to verify' ELSE 'checked' END AS basis_status
ORDER BY CASE WHEN v.aml THEN 0 ELSE 1 END, authority

// Which legislation applies to this sector?
// from: Sector | yields: Law
MATCH (s:Sector {id:$id})-[r:SUBJECT_TO]->(l:Law)
RETURN 'Law' AS _type, l.id AS _id, l.short AS law, l.title AS title, CASE WHEN l.valid_from IS NULL OR l.valid_from <= $on THEN 'in force' ELSE 'from ' + l.valid_from END AS status, r.source AS link_from
ORDER BY law

// Does this sector need a licence, which one, and who grants it?
// from: Sector | yields: Regulator
MATCH (s:Sector {id:$id})-[:REQUIRES_LICENCE]->(x:Licence)
OPTIONAL MATCH (x)-[:GRANTED_BY]->(g:Regulator)
RETURN 'Regulator' AS _type, g.id AS _id, x.kind AS kind, x.name AS licence, x.basis AS basis, g.short AS granted_by, CASE WHEN x.verify THEN 'to verify' ELSE 'checked' END AS basis_status

// Which duties does the office itself have in this sector on $on (organisation: risk assessment, training, sanctions procedure)?
// from: Sector | yields: SectorDuty
MATCH (s:Sector {id:$id})-[:HAS_DUTY]->(d:SectorDuty {level:'office'}) WHERE d.valid_from <= $on AND (d.valid_to IS NULL OR d.valid_to >= $on)
OPTIONAL MATCH (d)-[:DEFINED_IN]->(a:Article) WHERE (a.valid_from IS NULL OR a.valid_from <= $on) AND (a.valid_to IS NULL OR a.valid_to >= $on)
RETURN 'SectorDuty' AS _type, d.id AS _id, d.level AS level, d.title AS duty, coalesce(d.authority, 'supervisor') AS towards, collect(a.ref)[0] AS basis
ORDER BY level DESC, duty

// Which other sectors are in the same category, and who is their AML supervisor?
// from: Sector | yields: Sector
MATCH (s:Sector {id:$id})-[:IN_CATEGORY]->(c:SectorCategory)<-[:IN_CATEGORY]-(o:Sector) WHERE o <> s
OPTIONAL MATCH (g:Regulator)-[:SUPERVISES {aml:true}]->(o)
RETURN 'Sector' AS _type, o.id AS _id, c.name_nl AS category, o.local AS sector, g.short AS aml_supervisor
ORDER BY sector

// Which KYC duties does the office have per client in this sector on $on (CDD, reporting, screening, record keeping)?
// from: Sector | yields: SectorDuty
MATCH (s:Sector {id:$id})-[:HAS_DUTY]->(d:SectorDuty {level:'client'}) WHERE d.valid_from <= $on AND (d.valid_to IS NULL OR d.valid_to >= $on)
OPTIONAL MATCH (d)-[:DEFINED_IN]->(a:Article) WHERE (a.valid_from IS NULL OR a.valid_from <= $on) AND (a.valid_to IS NULL OR a.valid_to >= $on)
RETURN 'SectorDuty' AS _type, d.id AS _id, d.level AS level, d.title AS duty, coalesce(d.authority, 'supervisor') AS towards, collect(a.ref)[0] AS basis
ORDER BY level DESC, duty

// Which sectors does this authority supervise, and in which role?
// from: Regulator | yields: Sector
MATCH (g:Regulator {id:$id})-[v:SUPERVISES]->(s:Sector)-[:IN_CATEGORY]->(c:SectorCategory)
RETURN 'Sector' AS _type, s.id AS _id, c.name_nl AS category, s.local AS sector, CASE WHEN v.aml THEN 'AML supervisor' ELSE replace(coalesce(v.role, ''), '_', ' ') END AS role, c.order AS cat_order
ORDER BY cat_order, sector

// On what legal basis does this authority act, and where does that come from?
// from: Regulator | yields: -
MATCH (g:Regulator {id:$id})
RETURN g.short AS authority, g.name AS name, g.basis AS legal_basis, g.basis_url AS source, g.basis_source AS taken_from, CASE WHEN g.basis_verify THEN 'to verify' ELSE 'checked' END AS basis_status

// Which licences does this authority grant, and for which sectors?
// from: Regulator | yields: Sector
MATCH (s:Sector)-[:REQUIRES_LICENCE]->(x:Licence)-[:GRANTED_BY]->(g:Regulator {id:$id})
RETURN 'Sector' AS _type, s.id AS _id, s.local AS sector, x.kind AS kind, x.name AS licence, x.basis AS basis
ORDER BY sector

// Which sectors are subject to this law?
// from: Law | yields: Sector
MATCH (l:Law {id:$id})<-[r:SUBJECT_TO]-(s:Sector)-[:IN_CATEGORY]->(c:SectorCategory)
OPTIONAL MATCH (g:Regulator)-[:SUPERVISES {aml:true}]->(s)
RETURN 'Sector' AS _type, s.id AS _id, c.name_nl AS category, s.local AS sector, g.short AS aml_supervisor, r.source AS link_from, c.order AS cat_order
ORDER BY cat_order, sector

// Which articles of this law are in the register, in Dutch and in English?
// from: Law | yields: SectorDuty
MATCH (a:Article)-[:PART_OF]->(l:Law {id:$id}) OPTIONAL MATCH (d:SectorDuty)-[:DEFINED_IN]->(a)
RETURN 'SectorDuty' AS _type, d.id AS _id, a.ref AS article, d.title AS duty, a.text_local AS text_dutch, a.text_en AS text_english,
       CASE WHEN a.basis_kind = 'summary' THEN 'summary' WHEN a.verify THEN 'law text, to verify' ELSE 'law text, checked' END AS text_status
ORDER BY article

// Which sectors have this duty?
// from: SectorDuty | yields: Sector
MATCH (d:SectorDuty {id:$id})<-[:HAS_DUTY]-(s:Sector)-[:IN_CATEGORY]->(c:SectorCategory)
WITH * WHERE d.valid_from <= $on AND (d.valid_to IS NULL OR d.valid_to >= $on)
RETURN 'Sector' AS _type, s.id AS _id, c.name_nl AS category, s.local AS sector, c.order AS cat_order
ORDER BY cat_order, sector
